using System;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EasyRoads3Dv3;
namespace LWS.TruckSnake.Editor {
// EasyRoads owns terrain deformation. LWS supplies the saved road geometry and
// keeps bridges/jump gaps out of ground grading. Never regenerate Vista here.
public static class SnakeRoadGradeAuthoring {
 public static void Upgrade(){EditorSceneManager.OpenScene(SnakeAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<SnakeMatch>();SnakeAuthoring.EnsureGradeMarkers(m);Grade(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();}
 public static void Grade(SnakeMatch match){if(match.world.groundRoads==null||match.world.groundRoads.Length==0)throw new InvalidOperationException("Saved ground-road grade markers are required.");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EasyRoads3D/Resources/ERRoadNetwork.prefab");var instance=(GameObject)PrefabUtility.InstantiatePrefab(prefab);instance.name="Isolated Snake EasyRoads terrain grade";var report=new StringBuilder();report.AppendLine("BEFORE "+Clearance(match));try{var owner=instance.GetComponent<ERModularBase>();owner.RoadNetworkInit();var network=new ERRoadNetwork(owner);foreach(var line in match.world.groundRoads){var type=new ERRoadType{roadTypeName=line.name,roadWidth=line.width,hasMeshCollider=false};var controls=Enumerable.Repeat(ERMarkerControlType.StraightXZ,line.markers.Length).ToArray();var road=network.CreateRoad(line.name,type,line.markers,controls);road.SetTerrainDeformation(true,false);road.SnapToTerrain(false,false);for(int i=0;i<line.markers.Length;i++){road.SetIndent(line.width*.5f+2,i);road.SetSurrounding(line.width*.5f+18,i);}road.Refresh();}network.BuildRoadNetwork(false,false,false);foreach(var terrain in match.world.terrain)EditorUtility.SetDirty(terrain.terrainData);}finally{UnityEngine.Object.DestroyImmediate(instance);}Physics.SyncTransforms();report.AppendLine("AFTER "+Clearance(match));System.IO.File.WriteAllText("Logs/TruckSports/EssentialRelease/Snake/easyroads-grade.txt",report.ToString());EditorUtility.SetDirty(match.world);}
 static string Clearance(SnakeMatch m){float maximum=float.NegativeInfinity;int buried=0,samples=0,uncovered=0;var actual=UnityEngine.Object.FindObjectsByType<LWS.InterstateHauler.LwsRoadSurface>();foreach(var line in m.world.groundRoads){var shapes=actual.Where(r=>r.RoadId==line.name).Select(r=>r.GetComponent<Collider>()).Where(c=>c!=null).ToArray();for(int n=1;n<line.markers.Length;n++){var a=line.markers[n-1];var b=line.markers[n];int steps=Mathf.CeilToInt(Vector3.Distance(a,b)/3);for(int k=0;k<=steps;k++){var p=Vector3.Lerp(a,b,k/(float)steps);float top=float.NegativeInfinity;foreach(var shape in shapes)if(shape.Raycast(new Ray(p+Vector3.up*100,Vector3.down),out var hit,150))top=Mathf.Max(top,hit.point.y);if(float.IsNegativeInfinity(top)){uncovered++;continue;}float excess=m.world.Height(p)-top;maximum=Mathf.Max(maximum,excess);if(excess>.15f)buried++;samples++;}}}return "actualRoadColliderSamples="+samples+" buried="+buried+" nominalOutsideCurve="+uncovered+" highestTerrainAboveCollider="+maximum+"m";}
}
}
